const first = $input.first().json;
const raw = first.text ?? first.output ?? '';
const original = $('cuando recibe un mensaje de chat').first().json.chatInput ?? '';
let p = {}; let parse_ok = true;
try { const m = String(raw).match(/\{[\s\S]*\}/); p = JSON.parse(m ? m[0] : raw); } catch (e) { parse_ok = false; }
const INTENTS = ['ACCESS','TECHNICAL','OTHER']; const RISKS = ['LOW','MEDIUM','HIGH'];
let intent = String(p.intent || '').toUpperCase(); if (!INTENTS.includes(intent)) intent = 'OTHER';
let risk = String(p.risk || '').toUpperCase(); if (!RISKS.includes(risk)) risk = 'MEDIUM';
let confidence = Number(p.confidence); if (!isFinite(confidence)) confidence = 0; confidence = Math.min(1, Math.max(0, confidence));
let fallback_reason = '';
if (!parse_ok) { fallback_reason = 'La salida del clasificador no es JSON válido'; intent = 'OTHER'; }
else if (intent !== 'OTHER' && confidence < 0.7) { fallback_reason = 'Confianza insuficiente (' + confidence + ')'; intent = 'OTHER'; }
else if (intent === 'OTHER') { fallback_reason = 'Solicitud ambigua o fuera de alcance'; }
const em = String(original).match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const contacto = em ? em[0] : 'No informado';
return [{ json: { original_input: original, intent, confidence, risk, contacto, fallback_reason, classifier_parse_ok: parse_ok } }];

const WORKER = 'ACCESS'; const CATS = ["Acceso"]; const SETNAME = 'Preparar Payload Access';

const j = $input.first()?.json ?? {};
const sent = $(SETNAME).first().json;
const PRIOS = ['Urgente','Alta','Media','Baja']; const STAT = ['success','needs_info','error'];
const problems = [];
if (j.error) { const e = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error)); problems.push('Fallo de ejecución del Worker: ' + String(e).slice(0, 300)); }
else {
  if (!STAT.includes(j.status)) problems.push('status inválido');
  if (j.worker !== WORKER) problems.push('worker inesperado');
  if (!CATS.includes(j.categoria)) problems.push('categoria inválida');
  if (!PRIOS.includes(j.prioridad)) problems.push('prioridad inválida');
  if (typeof j.requires_human !== 'boolean') problems.push('requires_human no es booleano');
  if (typeof j.respuesta !== 'string' || !j.respuesta.trim()) problems.push('respuesta vacía');
}
const valid = problems.length === 0;
const result = valid ? { ...j } : { status: 'error', worker: WORKER, categoria: 'Sin clasificar', prioridad: 'Alta', impacto: 'No determinado', puede_continuar_trabajando: 'No determinado', respuesta: '', requires_human: true, motivo_escalamiento: 'Revisión humana requerida: ' + problems.join('; ') };
return [{ json: { worker_invoked: WORKER, worker_params: sent, worker_valid: valid, validation_errors: problems, result } }];

const WORKER = 'TECHNICAL'; const CATS = ["Hardware","Software","Red"]; const SETNAME = 'Preparar Payload Technical';

const j = $input.first()?.json ?? {};
const sent = $(SETNAME).first().json;
const PRIOS = ['Urgente','Alta','Media','Baja']; const STAT = ['success','needs_info','error'];
const problems = [];
if (j.error) { const e = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error)); problems.push('Fallo de ejecución del Worker: ' + String(e).slice(0, 300)); }
else {
  if (!STAT.includes(j.status)) problems.push('status inválido');
  if (j.worker !== WORKER) problems.push('worker inesperado');
  if (!CATS.includes(j.categoria)) problems.push('categoria inválida');
  if (!PRIOS.includes(j.prioridad)) problems.push('prioridad inválida');
  if (typeof j.requires_human !== 'boolean') problems.push('requires_human no es booleano');
  if (typeof j.respuesta !== 'string' || !j.respuesta.trim()) problems.push('respuesta vacía');
}
const valid = problems.length === 0;
const result = valid ? { ...j } : { status: 'error', worker: WORKER, categoria: 'Sin clasificar', prioridad: 'Alta', impacto: 'No determinado', puede_continuar_trabajando: 'No determinado', respuesta: '', requires_human: true, motivo_escalamiento: 'Revisión humana requerida: ' + problems.join('; ') };
return [{ json: { worker_invoked: WORKER, worker_params: sent, worker_valid: valid, validation_errors: problems, result } }];

const cls = $input.first().json;
const parseFail = String(cls.fallback_reason || '').startsWith('La salida del clasificador');
const msg = parseFail
  ? 'No pude interpretar tu solicitud con seguridad. ¿Puedes describir el problema (acceso a cuenta, hardware, software o red) e incluir tu correo de contacto? Si es urgente, una persona del equipo revisará tu caso.'
  : 'Hola, soy el asistente de soporte IT. Cuéntame qué problema tienes (acceso a cuentas, hardware, software, red o VPN) e incluye tu correo de contacto para poder ayudarte.';
return [{ json: { worker_invoked: 'NONE', worker_params: null, worker_valid: true, validation_errors: [], result: { status: 'needs_info', worker: 'NONE', categoria: 'Sin clasificar', prioridad: 'Baja', impacto: 'No determinado', puede_continuar_trabajando: 'No determinado', respuesta: msg, requires_human: false, motivo_escalamiento: 'Solicitud ambigua o fuera de alcance; se solicita aclaración' } } }];

const j = $input.first().json;
const cls = $('Normalizar Clasificación').first().json;
const contactValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cls.contacto || '');
const invoked = j.worker_invoked !== 'NONE';
const r = j.result || {};
let skip = '';
if (!invoked) skip = 'Sin Worker invocado (fallback)';
else if (!j.worker_valid) skip = 'Resultado del Worker inválido o con error';
else if (r.status !== 'success') skip = 'El Worker devolvió status ' + r.status;
else if (!contactValid) skip = 'Falta contacto válido del usuario';
const ts = $now.toFormat('yyyy-LL-dd HH:mm:ss');
return [{ json: {
  timestamp: ts, execution_id: String($execution.id),
  original_input: cls.original_input, intent: cls.intent, confidence: cls.confidence, risk: cls.risk, fallback_reason: cls.fallback_reason,
  contact_valid: contactValid, worker_invoked: j.worker_invoked, worker_params: j.worker_params ?? null, worker_valid: j.worker_valid, validation_errors: j.validation_errors ?? [], result: r,
  ticket_eligible: skip === '', ticket_skip_reason: skip,
  fecha_hora: ts, contacto: cls.contacto, descripcion_problema: cls.original_input, categoria: r.categoria, prioridad: r.prioridad, impacto: r.impacto,
  puede_continuar_trabajando: r.puede_continuar_trabajando, recomendacion: r.respuesta, requiere_escalamiento: r.requires_human ? 'Sí' : 'No'
} }];

const c = $('Consolidar Resultado').first().json;
const inp = $input.first().json;
let ticket_result;
if (inp.ticket_eligible === false) ticket_result = 'NO REGISTRADO: ' + c.ticket_skip_reason;
else if (inp.error) ticket_result = 'ERROR AL REGISTRAR: ' + (typeof inp.error === 'string' ? inp.error : (inp.error.message || 'error desconocido'));
else if (inp.contacto || inp.descripcion_problema || inp.row_number) ticket_result = 'REGISTRADO (confirmado por Google Sheets)';
else ticket_result = 'SIN CONFIRMACIÓN de Google Sheets';
const r = c.result;
const L = [];
L.push('REPORTE DE EJECUCIÓN - IT Support Triage (Checkpoint 2, Manager-Worker)');
L.push('Fecha/hora: ' + c.timestamp);
L.push('Execution ID: ' + c.execution_id);
L.push('Entrada original: ' + c.original_input);
L.push('Intención clasificada: ' + c.intent + ' (confianza ' + c.confidence + ', riesgo ' + c.risk + ')');
L.push('Motivo de fallback: ' + (c.fallback_reason || 'N/A'));
L.push('Worker invocado: ' + c.worker_invoked);
L.push('Parámetros enviados al Worker: ' + JSON.stringify(c.worker_params));
L.push('Estado del Worker: ' + r.status + (c.worker_valid ? ' (salida válida)' : ' (salida inválida o con error)'));
L.push('Errores de validación: ' + (c.validation_errors.length ? c.validation_errors.join('; ') : 'ninguno'));
L.push('Categoría: ' + r.categoria + ' | Prioridad: ' + r.prioridad);
L.push('Escalamiento humano: ' + (r.requires_human ? 'Sí' : 'No') + (r.motivo_escalamiento ? ' - ' + r.motivo_escalamiento : ''));
L.push('Resultado de registro de ticket: ' + ticket_result);
L.push('Respuesta estructurada del Worker:');
L.push(JSON.stringify(r, null, 2));
let msg = r.respuesta || '';
if (c.worker_invoked !== 'NONE') {
  if (!c.worker_valid) msg = 'No pude obtener un análisis confiable de tu caso. Se requiere revisión humana.';
  else {
    if (r.requires_human) msg += '\n\nTu caso requiere atención de una persona del equipo de soporte.';
    if (ticket_result.startsWith('REGISTRADO')) msg += '\n\nTicket registrado.';
    else if (!c.contact_valid) msg += '\n\nPara registrar tu ticket necesito un correo de contacto válido. ¿Me lo puedes compartir?';
    else msg += '\n\nNo pude confirmar el registro del ticket; una persona del equipo lo revisará.';
  }
}
return [{ json: { ...c, ticket_result, observability_body: L.join('\n'), output: msg } }];

const sid = String($json.sessionId || '').trim();
if (!/^[A-Za-z0-9_.:-]{3,128}$/.test(sid)) {
  throw new Error('Session_ID ausente o inválido: el flujo se detiene sin consultar ni modificar la memoria.');
}
return [{ json: { Session_ID: sid, chatInput: String($json.chatInput || '').trim() } }];

const base = $('Capturar Session_ID').first().json;
const clean = v => (v === undefined || v === null) ? '' : String(v).trim();
const rows = $input.all().map(i => i.json).filter(r => clean(r.Session_ID) === base.Session_ID);
const r = rows[0];
const es_nueva = !r;
return [{ json: {
  Session_ID: base.Session_ID,
  chatInput: base.chatInput,
  es_nueva,
  user_name: clean(r && r.user_name) || 'No registrado',
  case_status: clean(r && r['Estado del Caso']) || 'Nuevo',
  last_summary: clean(r && r['Resumen Consolidado']) || 'Sin resumen previo',
  key_data: clean(r && r['Datos Clave']) || 'Sin datos clave',
  prev_count: Number(r && r.message_count) || 0,
  prev_summary_raw: clean(r && r['Resumen Consolidado'])
} }];

// Une ambas ramas (sesión nueva / recurrente) en una estructura única y sin variables undefined.
const m = $('Normalizar Memoria').first().json;
return [{ json: { ...m } }];

