const ctx = $('Preparar Contexto').first().json;
const items = $input.all().map(i => i.json);
let msgs = [];
for (const j of items) { if (Array.isArray(j.messages)) msgs = msgs.concat(j.messages); else msgs.push(j); }
const txt = m => {
  if (m.human !== undefined) return 'Usuario: ' + m.human;
  if (m.ai !== undefined) return 'Agente: ' + m.ai;
  if (m.type && m.content !== undefined) return (m.type === 'human' ? 'Usuario: ' : 'Agente: ') + m.content;
  return String(JSON.stringify(m));
};
const historial = msgs.slice(-14).map(m => txt(m).slice(0, 500)).join('\n');
const message_count = ctx.prev_count + 1;
return [{ json: { Session_ID: ctx.Session_ID, message_count, resumir: message_count > 5, historial_reciente: historial, resumen_previo: ctx.prev_summary_raw || 'Ninguno' } }];

