let out = $json.output !== undefined ? $json.output : $json.text;
let obj = null;
try {
  if (typeof out === 'string') {
    const limpio = out.replace(/```json|```/gi, '').trim();
    const m = limpio.match(/\{[\s\S]*\}/);
    obj = JSON.parse(m ? m[0] : limpio);
  } else { obj = out; }
} catch (e) { obj = null; }
const keys = obj && typeof obj === 'object' ? Object.keys(obj).sort().join(',') : '';
const ok = keys === 'accion_requerida,asunto_principal,puntos_clave'
  && typeof obj.asunto_principal === 'string' && obj.asunto_principal.trim() !== ''
  && typeof obj.accion_requerida === 'string'
  && Array.isArray(obj.puntos_clave) && obj.puntos_clave.every(p => typeof p === 'string');
if (!ok) { return [{ json: { summary_ok: false, motivo: 'JSON inválido: se conserva el resumen previo' } }]; }
const limpio = {
  asunto_principal: obj.asunto_principal.trim().slice(0, 300),
  puntos_clave: obj.puntos_clave.map(p => p.trim().slice(0, 200)).filter(Boolean).slice(0, 6),
  accion_requerida: obj.accion_requerida.trim().slice(0, 300)
};
return [{ json: { summary_ok: true, resumen_json: JSON.stringify(limpio), puntos: limpio.puntos_clave } }];

const ctx = $('Preparar Contexto').first().json;
const cnt = $('Contar mensajes').first().json;
const est = $('Estado del Ticket').first().json;
let nuevo = null;
try { const v = $('Validar JSON del resumen').first().json; if (v && v.summary_ok) nuevo = v; } catch (e) { nuevo = null; }
// Nombre: solo se actualiza si el usuario se presenta explícitamente
const mm = String(ctx.chatInput || '').match(/(?:soy|me llamo|mi nombre es|i am|my name is)\s+([A-ZÁÉÍÓÚÑ][A-Za-zÁÉÍÓÚÑáéíóúñ]+(?:\s+[A-ZÁÉÍÓÚÑ][A-Za-zÁÉÍÓÚÑáéíóúñ]+)?)/);
const user_name = mm ? mm[1] : (ctx.user_name !== 'No registrado' ? ctx.user_name : 'No registrado');
const ticket = String(est.ticket_result || 'N/A').slice(0, 40);
const estado = ticket.toUpperCase().includes('REGISTRADO') && !ticket.toUpperCase().includes('NO REGISTRADO') ? 'Ticket registrado' : (est.intent === 'OTHER' ? 'Pendiente de aclaración' : 'En seguimiento');
const resumen = nuevo ? nuevo.resumen_json : (ctx.prev_summary_raw || '');
const datos = ('intent=' + (est.intent || 'N/A') + '; ticket=' + ticket + (nuevo ? '; puntos=' + nuevo.puntos.join(' | ') : '')).slice(0, 500);
return [{ json: {
  Session_ID: ctx.Session_ID,
  'Fecha de Actualización': new Date().toISOString(),
  'Resumen Consolidado': resumen,
  'Estado del Caso': estado,
  'Datos Clave': datos,
  user_name,
  message_count: cnt.message_count,
  resumen_actualizado: !!nuevo
} }];

const e = $('Estado del Ticket').first().json;
let texto = e.output;
try { const a = $('Agente Principal (Tools Agent)').first().json.output; if (a && String(a).trim()) texto = a; } catch (err) {}
const m = $('Preparar actualización de memoria').first().json;
return [{ json: { output: texto, intent: e.intent, worker_invoked: e.worker_invoked, ticket_result: e.ticket_result, execution_id: e.execution_id, Session_ID: m.Session_ID, message_count: m.message_count } }];

const m = $json;
const hdr = {};
const put = (k, v) => { if (k) hdr[String(k).toLowerCase()] = String(v === undefined || v === null ? '' : v); };
if (m.headers && typeof m.headers === 'object' && !Array.isArray(m.headers)) Object.entries(m.headers).forEach(([k, v]) => put(k, v));
const ph = (m.payload && m.payload.headers) || (Array.isArray(m.headers) ? m.headers : []);
ph.forEach(h => put(h.name, h.value));
const fromObj = (m.from && m.from.value && m.from.value[0]) || {};
let address = String(fromObj.address || '').trim().toLowerCase();
let nombre = String(fromObj.name || '').trim();
if (!address && typeof m.from === 'string') { const mm = m.from.match(/<([^>]+)>/); address = (mm ? mm[1] : m.from).trim().toLowerCase(); nombre = nombre || m.from.replace(/<[^>]*>/, '').replace(/"/g, '').trim(); }
const asunto = String(m.subject || '').trim();
const cuerpo = String(m.text || m.snippet || '').trim();
const motivos = [];
if (/^(no-?reply|noreply|do-?not-?reply|donotreply|mailer-daemon|postmaster|bounce|notifications?)([+._-].*)?@/i.test(address)) motivos.push('remitente no-reply');
if (/^(bulk|junk|list|auto_reply)$/i.test((hdr['precedence'] || '').trim())) motivos.push('Precedence: ' + hdr['precedence']);
if ((hdr['auto-submitted'] || '').trim() && !/^no$/i.test(hdr['auto-submitted'].trim())) motivos.push('Auto-Submitted');
if (hdr['x-autoreply'] || hdr['x-autorespond'] || hdr['x-auto-response-suppress']) motivos.push('cabecera de autorrespuesta');
if (hdr['list-id'] || hdr['list-unsubscribe']) motivos.push('lista de correo');
if (/^(auto(matic)? ?reply|respuesta autom|out of office|fuera de (la )?oficina|undeliverable|delivery status|failure notice|no se pudo entregar)/i.test(asunto)) motivos.push('asunto de autorrespuesta');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(address)) motivos.push('remitente sin email válido');
if (cuerpo === '') motivos.push('cuerpo vacío');
const threadId = String(m.threadId || m.id || '').replace(/[^A-Za-z0-9]/g, '');
if (!threadId) motivos.push('sin threadId');
return [{ json: { ignorar: motivos.length > 0, motivo: motivos.join('; '), sessionId: 'gmail_' + threadId, chatInput: (asunto ? 'Asunto: ' + asunto + String.fromCharCode(10) : '') + cuerpo.slice(0, 4000), origen: 'gmail', email: address, nombre, asunto, threadId, messageId: String(m.id || '') } }];

const ctx = $('Estado del Ticket').first().json;
let gm = null;
try { if ($('Filtrar y normalizar correo').isExecuted) gm = $('Filtrar y normalizar correo').first().json; } catch (e) { gm = null; }
const texto = String($('Capturar Session_ID').first().json.chatInput || '');
let email = gm ? String(gm.email || '') : '';
if (!email) { const mm = texto.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/); email = mm ? mm[0] : ''; }
email = email.trim().toLowerCase();
const valido = /^[a-z0-9._%+-]+@[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}$/.test(email) && email.length <= 254 && !/^(no-?reply|noreply|do-?not-?reply|mailer-daemon|postmaster)@/.test(email);
let nombre = gm ? String(gm.nombre || '').trim() : '';
if (!nombre) nombre = String($('Preparar Contexto').first().json.user_name || '').trim();
if (/^no registrado$/i.test(nombre)) nombre = '';
const partes = nombre.split(/\s+/).filter(Boolean);
return [{ json: { hs_email: email, hs_valido: valido, hs_motivo: valido ? '' : 'email ausente o inválido: no se consulta ni escribe en HubSpot', hs_firstname: partes[0] || '', hs_lastname: partes.slice(1).join(' '), hs_intent: String(ctx.intent || ''), hs_origen: gm ? 'gmail' : 'chat' } }];

const p = $('Preparar contacto HubSpot').first().json;
const hits = $input.all().map(i => i.json).filter(r => r && (r.id || r.vid));
const t = r => new Date(r.createdAt || (r.properties && r.properties.createdate && (r.properties.createdate.value || r.properties.createdate)) || 0).getTime() || 0;
hits.sort((a, b) => t(a) - t(b));
return [{ json: { ...p, hs_existe: hits.length > 0, hs_contact_id: hits.length ? String(hits[0].id || hits[0].vid) : '', hs_duplicados: hits.length > 1, hs_total: hits.length } }];

const et = $('Estado del Ticket').first().json;
const p = $('Preparar contacto HubSpot').first().json;
let r = {};
try { if ($('Resolver contacto HubSpot').isExecuted) r = $('Resolver contacto HubSpot').first().json; } catch (e) { r = {}; }
let accion = 'omitido'; let w = null;
try { if ($('Crear contacto HubSpot').isExecuted) { accion = 'creado'; w = $('Crear contacto HubSpot').first().json; } } catch (e) {}
try { if ($('Actualizar contacto HubSpot').isExecuted) { accion = 'actualizado'; w = $('Actualizar contacto HubSpot').first().json; } } catch (e) {}
const err = w && w.error ? (typeof w.error === 'string' ? w.error : (w.error.message || 'error desconocido')) : '';
return [{ json: { ...et, hubspot_accion: err ? 'error' : accion, hubspot_email: p.hs_email, hubspot_contact_id: String((w && (w.id || w.vid)) || r.hs_contact_id || ''), hubspot_duplicados: !!r.hs_duplicados, hubspot_nota: p.hs_valido ? err : p.hs_motivo } }];

const f = $('Respuesta Final (con memoria)').first().json;
const h = $('Consolidar resultado HubSpot').first().json;
const urgente = /urgente|cr[ií]tico|ca[ií]do|ca[ií]da|producci[oó]n|seguridad|brecha|ransomware/i.test(String($('Capturar Session_ID').first().json.chatInput || ''));
const sinTicket = /NO REGISTRADO|ERROR|SIN CONFIRMACI/i.test(String(f.ticket_result || ''));
return [{ json: { escalar: urgente || sinTicket, slack_texto: 'IT Triage | intención: ' + f.intent + ' | ticket: ' + f.ticket_result + ' | HubSpot: ' + h.hubspot_accion + ' | sesión: ' + f.Session_ID, slack_escalacion: ':rotating_light: Escalación IT Triage | intención: ' + f.intent + ' | ' + (urgente ? 'palabras de urgencia detectadas' : 'ticket sin registrar') + ' | sesión: ' + f.Session_ID } }];
